      "bj004",
      "bj001",
      "bj003",
      "bj002",
      "bj006"
    ],
    "poi_notes": {
      "bj004": "中国国家博物馆：室内比例高、雨热适宜、参观强度中等，适合高温日与老年人，推荐作为某日下午或午后活动以避热。",
      "bj001": "故宫博物院：世界遗产，混合室内/户外，步行与强度偏高，推荐安排在清晨或早上入场并控制参观时长（约3-4小时），中途安排休息。",
      "bj003": "颐和园：园林与湖景，户外比例高、步行强度高，适合气温较凉的时段（早晨）或选择乘船与轻松步行结合，注意高温条件下的体力消耗。",
      "bj002": "天坛公园：户外古建筑与公园，参观强度中等，适合上午或傍晚，避免正午暴晒。",
      "bj006": "什刹海：低强度休闲湖区/胡同，适合作为傍晚或晚间轻松活动，步行量低，可作为行程缓冲放松点。"
    },
    "weather_risks": {
