    },
    "itinerary": {
      "daily_itinerary": [
        {
          "day": 1,
          "date": "2026-08-03",
          "attraction_poi_ids": [
            "bj001",
            "bj006"
          ],
          "notes": "上午：故宫博物院（尽量早入场，参观3-4小时，中途安排休息与坐椅休息）。午后回酒店休息或在附近选择室内午餐与午休。傍晚：什刹海轻松散步或乘船，节奏放慢，避免长时间站立。"
        },
        {
          "day": 2,
          "date": "2026-08-04",
          "attraction_poi_ids": [
            "bj003"
          ],
          "notes": "上午：颐和园（尽早前往，优先乘船游湖与乘坐园区内交通工具减少步行）；中午返回酒店休息。下午/傍晚安排休闲或返回酒店休息。"
        },
        {
          "day": 3,
          "date": "2026-08-05",
          "attraction_poi_ids": [
            "bj004",
            "bj002"
          ],
          "notes": "上午或下午：中国国家博物馆（室内，适合高温时段参观，安排2-3小时），如时间与体力允许可前往天坛公园做短时参观（推荐上午或傍晚，避开正午）。整体节奏轻松，午后预留充足休息时间，准备返程。"
        }
      ]
    },
    "budget": {
      "feasibility": true,
      "budget_notes": "总体预算8000元人民币对4位老年游客出行（含门票、交通、餐饮、住宿及少量购物）在中等消费水平下总体可行，但需注意：仅知故宫门票60元/人（证据中）。其它景点门票、餐饮与住宿费用未在证据中明确，需要在实际预订时核实。建议将预算分配为：门票与景区交通约占15%-20%，每日餐饮与市内交通约占30%-35%，住宿约占30%-40%，预留10%作为应急与医药开支。若选择中心地段中档酒店并控制餐饮与出行方式，8000元应能覆盖3天行程。",
      "recommended_total": 8000
